#!/bin/bash
set -euo pipefail
exec /usr/bin/python3 -I -B /dev/fd/3 "$@" 3<<'NSI_PYTHON_END'
BOOTSTRAP_ZIP=''
BOOTSTRAP_SHA='c329c6256a2e2e85a1e7dfd4d7f2f6e6f80b6c37a429ecac0e027ed79442b98b'
RELEASE_SHA='566fc9f88d040c71da6ac552b8357a33c0406702a5d2037485141d1f13d3b4c4'
PAYLOAD=''
INSTALLER='"""Root installer embedded verbatim in the pinned public launcher."""\nimport hashlib\nimport io\nimport json\nimport os\nfrom pathlib import Path, PurePosixPath\nimport shutil\nimport stat\nimport sys\nimport tarfile\nimport tempfile\n\n\ndef trusted_tree(path, owner=0):\n    paths = [path,*path.rglob(\'*\')]\n    for p in paths:\n        st = p.lstat()\n        if p.is_symlink() or st.st_uid != owner or st.st_mode & 0o022:\n            raise ValueError(\'Untrusted installation entry\')\n        if not stat.S_ISDIR(st.st_mode) and not stat.S_ISREG(st.st_mode):\n            raise ValueError(\'Unexpected installation object type\')\n\n\ndef install(archive, expected, root=Path(\'/opt/nosana-security-inspector/releases\'), owner=0):\n    if hashlib.sha256(archive).hexdigest() != expected:\n        raise ValueError(\'Release digest mismatch\')\n    with tarfile.open(fileobj=io.BytesIO(archive),mode=\'r:gz\') as t:\n        members = t.getmembers()\n        if len(members)>10000 or sum(m.size for m in members)>256*1024*1024:\n            raise ValueError(\'Bundle limit exceeded\')\n        names=set()\n        for m in members:\n            p=PurePosixPath(m.name)\n            if p.is_absolute() or \'..\' in p.parts or not m.isfile() or str(p) in names:\n                raise ValueError(\'Unsafe or duplicate bundle member\')\n            names.add(str(p))\n        manifest=json.load(t.extractfile(\'release.json\'))\n        if names != set(manifest[\'files\'])|{\'release.json\'}:\n            raise ValueError(\'Unmanifested archive contents\')\n        current=Path(root.anchor)\n        for part in root.parts[1:]:\n            current=current/part\n            if current.is_symlink(): raise ValueError(\'Unsafe installation path\')\n            existed=current.exists()\n            current.mkdir(mode=0o755,exist_ok=True)\n            if not existed: current.chmod(0o755)\n            st=current.stat()\n            # /tmp fixtures can have shared ancestors; never allow this on live install.\n            if owner==0 and (st.st_uid!=0 or st.st_mode&0o022):\n                raise ValueError(\'Untrusted installation directory\')\n        target=root/expected\n        if target.is_symlink(): raise ValueError(\'Unsafe cached target\')\n        if not target.exists():\n            stage=Path(tempfile.mkdtemp(prefix=\'.stage-\',dir=root))\n            try:\n                for m in members:\n                    dst=stage/m.name\n                    dst.parent.mkdir(parents=True,exist_ok=True)\n                    with dst.open(\'xb\') as f: f.write(t.extractfile(m).read())\n                    dst.chmod(0o755 if m.mode&0o111 else 0o644)\n                stage.chmod(0o755)\n                for directory in stage.rglob(\'*\'):\n                    if directory.is_dir(): directory.chmod(0o755)\n                verify(stage,manifest,owner)\n                os.rename(stage,target)\n            finally:\n                if stage.exists(): shutil.rmtree(stage)\n        verify(target,manifest,owner)\n        return target\n\n\ndef verify(target,manifest,owner):\n    trusted_tree(target,owner)\n    if json.loads((target/\'release.json\').read_text()) != manifest:\n        raise ValueError(\'Cached manifest differs from authenticated release\')\n    observed={str(p.relative_to(target)) for p in target.rglob(\'*\') if p.is_file()}\n    if observed != set(manifest[\'files\'])|{\'release.json\'}:\n        raise ValueError(\'Unexpected cached release files\')\n    for name,wanted in manifest[\'files\'].items():\n        p=target/name\n        if not p.resolve().is_relative_to(target.resolve()) or hashlib.sha256(p.read_bytes()).hexdigest()!=wanted:\n            raise ValueError(\'Member verification failed\')\n\n\nif __name__==\'__main__\':\n    if os.geteuid()!=0: raise SystemExit(\'Root installation required\')\n    try:\n        target=install(Path(sys.argv[1]).read_bytes(),sys.argv[2])\n        os.execv(str(target/\'inspect.sh\'),[str(target/\'inspect.sh\'),*sys.argv[3:]])\n    except Exception as exc:\n        raise SystemExit(\'Release installation refused: \'+type(exc).__name__)\n'

import base64,getpass,hashlib,io,os,pathlib,platform,subprocess,sys,tarfile,tempfile,zipfile
if sys.version_info<(3,10) or platform.system()!='Linux' or platform.machine()!='x86_64':
 raise SystemExit('This release supports Linux x86_64 with Python 3.10+ only.')
args=sys.argv[1:]
with tempfile.TemporaryDirectory(prefix='nosana-inspector-') as tmp:
 root=pathlib.Path(tmp)
 raw=base64.b64decode(BOOTSTRAP_ZIP,validate=True)
 if hashlib.sha256(raw).hexdigest()!=BOOTSTRAP_SHA: raise SystemExit('Bootstrap integrity mismatch')
 with zipfile.ZipFile(io.BytesIO(raw)) as z:
  for name in z.namelist():
   p=pathlib.PurePosixPath(name)
   if p.is_absolute() or '..' in p.parts: raise SystemExit('Unsafe bootstrap member')
   dst=root/pathlib.Path(*p.parts); dst.parent.mkdir(parents=True,exist_ok=True); dst.write_bytes(z.read(name))
 sys.path.insert(0,str(root))
 import pyrage
 password=os.environ.pop('NSI_PASSWORD',None)
 if password is None:
  password=getpass.getpass('Inspector sharing password: ')
 try: payload=pyrage.passphrase.decrypt(base64.b64decode(PAYLOAD,validate=True),password)
 except Exception: raise SystemExit('Password or encrypted release authentication failed.')
 password=None
 if hashlib.sha256(payload).hexdigest()!=RELEASE_SHA: raise SystemExit('Release integrity mismatch')
 if args==['--show-source']:
  with tarfile.open(fileobj=io.BytesIO(payload),mode='r:gz') as t:
   for m in t.getmembers():
    if m.name.endswith(('.py','.sh','.md','.json')):
     print('\n# FILE: '+m.name); print(t.extractfile(m).read().decode('utf-8','replace'))
  raise SystemExit(0)
 archive=root/'release.tar.gz'; archive.write_bytes(payload); archive.chmod(0o600); payload=None
 env={k:v for k,v in os.environ.items() if k not in ('NSI_PASSWORD','PYTHONPATH','PYTHONHOME','LD_PRELOAD','LD_LIBRARY_PATH')}
 if os.geteuid()==0:
  cmd=['/usr/bin/python3','-I','-B','-c',INSTALLER,str(archive),RELEASE_SHA,*args]
 else:
  cmd=['sudo','--','/usr/bin/python3','-I','-B','-c',INSTALLER,str(archive),RELEASE_SHA,*args]
 raise SystemExit(subprocess.call(cmd,env=env))

NSI_PYTHON_END
